{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, attr_k8s_pod_name, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'geo%' ORDER BY time", "claim": "Geo pod restart count climbs from 2 to 6 during the incident and it stops emitting after 02:54:15."},
        {"kind": "metric", "sql": "SELECT time, metric, value FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='geo' ORDER BY time", "claim": "Geo deployment availability stays at 0 for the whole abnormal window, versus 1 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) c FROM abnormal_traces WHERE service_name='geo' GROUP BY 1,2,3", "claim": "Geo emits no spans in the abnormal window, while normal has 886 geo.Geo/Nearby server spans."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE message LIKE '%geo%' GROUP BY 1,2,3", "claim": "Search logs 711 errors 'Failed to get nearby hotels from geo service' during the incident."}
      ]
    },
    {
      "service": "reservation",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, attr_k8s_pod_name, value FROM abnormal_metrics WHERE metric='container.memory.rss' AND attr_k8s_pod_name LIKE 'reservation%' ORDER BY time", "claim": "Reservation pod RSS jumps from about 15 MB in normal to about 1.03 GB from onset and stays flat."},
        {"kind": "metric", "sql": "SELECT p, metric, round(avg(value),2) av FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE attr_k8s_pod_name LIKE 'reservation%' AND metric IN ('container.memory.usage','container.cpu.usage') GROUP BY 1,2", "claim": "Reservation container memory averages about 1.0 GB abnormal versus 20 MB normal, while CPU falls."},
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) c, round(quantile_cont(duration,0.95)/1e6,2) p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend' AND span_name IN ('HTTP /reservation','reservation.Reservation/CheckAvailability') GROUP BY 1,2", "claim": "Frontend's /reservation and reservation CheckAvailability calls run slightly slower in abnormal, the only user-facing effect of reservation."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT round(avg(duration)/1e6,2) avg_ms, count(*) c FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' AND attr_status_code='Error'", "claim": "Search's calls to geo fail quickly with Error status, about 0.01 ms each, and no longer succeed."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2", "claim": "Frontend's HTTP /hotels returns 500 for about 697 requests, matching search's failed Nearby calls."}
      ]
    },
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, round(quantile_cont(duration,0.5)/1e6,2) p50_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend' AND span_name='HTTP /reservation' GROUP BY 1", "claim": "Frontend's HTTP /reservation median rises from about 3.5 ms to 3.8 ms in the incident window."}
      ]
    }
  ]
}

